-- ===============================================================
-- TALLY SHEET - SUPABASE POSTGRESQL SCHEMA & PRODUCTION SETUP
-- Project URL: https://jooffdovcomgyvvsftmf.supabase.co
--
-- STATUS: PRODUCTION LIVE SAFE (100% NON-DESTRUCTIVE)
-- JAMINAN KEAMANAN DATABASE LIVE:
-- 1. Script ini 100% AMAN dijalankan di database Supabase yang SUDAH GO-LIVE.
-- 2. TIDAK ADA perintah destruktif: TIDAK ADA DROP TABLE, DROP SCHEMA, TRUNCATE, atau DELETE.
-- 3. Semua tabel dibuat dengan klausa `CREATE TABLE IF NOT EXISTS`.
-- 4. Semua kolom migrasi ditambahkan dengan `ALTER TABLE ... ADD COLUMN IF NOT EXISTS`.
-- 5. Semua indeks dibuat dengan `CREATE INDEX IF NOT EXISTS`.
-- 6. Seluruh SEED DATA (Users, Settings, Materials) menggunakan `ON CONFLICT DO NOTHING`.
--    -> Data live di Supabase (user, password, konfigurasi, data transaksi Tally Sheet)
--       TIDAK AKAN PERNAH DIHAPUS ATAU DITIMPA.
--
-- PANDUAN EKSEKUSI DI SUPABASE:
-- 1. Buka Dashboard Supabase: https://supabase.com/dashboard/project/jooffdovcomgyvvsftmf
-- 2. Masuk ke menu "SQL Editor" (ikon query di sidebar kiri)
-- 3. Klik "+ New query"
-- 4. Salin seluruh isi file ini (Ctrl+A, Ctrl+C), lalu paste ke editor
-- 5. Klik tombol "Run" (atau Ctrl+Enter)
-- ===============================================================

-- 1. USERS TABLE
CREATE TABLE IF NOT EXISTS public.users (
    id TEXT PRIMARY KEY,
    email TEXT UNIQUE NOT NULL,
    name TEXT NOT NULL,
    password_hash TEXT NOT NULL,
    role TEXT NOT NULL DEFAULT 'user',
    is_pic INTEGER NOT NULL DEFAULT 1,
    active INTEGER NOT NULL DEFAULT 1,
    created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc', now())
);
CREATE INDEX IF NOT EXISTS idx_users_email ON public.users(email);

-- 2. SETTINGS TABLE
CREATE TABLE IF NOT EXISTS public.settings (
    id TEXT PRIMARY KEY,
    required_json TEXT NOT NULL,
    duplicate_rule TEXT NOT NULL,
    hold_categories_json TEXT DEFAULT '[]',
    qa_documents_json TEXT DEFAULT '{}',
    role_permissions_json TEXT DEFAULT '{}',
    webhook_config_json TEXT DEFAULT '{}',
    updated_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc', now()),
    updated_by_name TEXT NOT NULL
);
ALTER TABLE public.settings ADD COLUMN IF NOT EXISTS hold_categories_json TEXT DEFAULT '[]';
ALTER TABLE public.settings ADD COLUMN IF NOT EXISTS qa_documents_json TEXT DEFAULT '{}';
ALTER TABLE public.settings ADD COLUMN IF NOT EXISTS role_permissions_json TEXT DEFAULT '{}';
ALTER TABLE public.settings ADD COLUMN IF NOT EXISTS webhook_config_json TEXT DEFAULT '{}';

-- 3. MASTER VERSIONS TABLE
CREATE TABLE IF NOT EXISTS public.master_versions (
    id TEXT PRIMARY KEY,
    version INTEGER NOT NULL,
    filename TEXT NOT NULL,
    mode TEXT NOT NULL,
    uploaded_by TEXT NOT NULL,
    uploaded_by_name TEXT NOT NULL,
    uploaded_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc', now()),
    total_rows INTEGER NOT NULL,
    valid_rows INTEGER NOT NULL,
    error_rows INTEGER NOT NULL,
    inserted INTEGER NOT NULL,
    updated INTEGER NOT NULL,
    deactivated INTEGER NOT NULL,
    active_total INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_master_versions_ver ON public.master_versions(version DESC);

-- 4. MATERIALS TABLE
CREATE TABLE IF NOT EXISTS public.materials (
    id TEXT PRIMARY KEY,
    code TEXT UNIQUE NOT NULL,
    name TEXT NOT NULL,
    extra_json TEXT NOT NULL DEFAULT '{}',
    active INTEGER NOT NULL DEFAULT 1,
    version_id TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc', now()),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc', now())
);
CREATE INDEX IF NOT EXISTS idx_materials_code ON public.materials(code);
CREATE INDEX IF NOT EXISTS idx_materials_name ON public.materials(name);
CREATE INDEX IF NOT EXISTS idx_materials_active ON public.materials(active);

-- 5. TALLY SHEETS TABLE
CREATE TABLE IF NOT EXISTS public.tally_sheets (
    id TEXT PRIMARY KEY,
    doc_no TEXT UNIQUE NOT NULL,
